import numpy as np
from gensim import matutils
from numpy import dot, array


class VectorUtil:
    # Logical shift left by 0 bits is identity, so we can inline this
    # as the value unchanged. But since it's a simple op, no refactor needed.
    # Actually, no magic number here.

    # Magic number '1' in log smoothing - replace with symbolic constant
    IDF_SMOOTHING_OFFSET = 1

    @staticmethod
    def similarity(vector_1, vector_2):
        return dot(matutils.unitvec(vector_1), matutils.unitvec(vector_2))

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        norm = np.linalg.norm(vector_1)
        all_norms = np.linalg.norm(vectors_all, axis=1)
        dot_products = dot(vectors_all, vector_1)
        return dot_products / (norm * all_norms)

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        if len(vector_list_1) == 0 or len(vector_list_2) == 0:
            raise ZeroDivisionError('At least one of the passed list is empty.')

        mean_1 = np.mean(np.array(vector_list_1), axis=0)
        mean_2 = np.mean(np.array(vector_list_2), axis=0)

        return dot(matutils.unitvec(mean_1), matutils.unitvec(mean_2))

    @staticmethod
    def _build_index_to_key_map(number_dict):
        index_2_key_map = {}
        count_list = []
        for index, (key, count) in enumerate(number_dict.items()):
            index_2_key_map[index] = key
            count_list.append(count)
        return index_2_key_map, count_list

    @staticmethod
    def _compute_idf_weights(count_array):
        smoothed = np.log((VectorUtil.IDF_SMOOTHING_OFFSET + 1) / (count_array + VectorUtil.IDF_SMOOTHING_OFFSET))
        return smoothed

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        index_2_key_map, count_list = VectorUtil._build_index_to_key_map(number_dict)
        count_array = np.array(count_list)
        weights = VectorUtil._compute_idf_weights(count_array)
        result = {key: weights[index] for index, key in index_2_key_map.items()}
        return result
